#!/usr/bin/env python3
"""Add blog posts 10-24 to lib/blog.ts"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BLOG_TS = ROOT / "lib" / "blog.ts"

def para(*s): return " ".join(s)
def section(title, *paragraphs, level=2):
    return f"\n{'#'*level} {title}\n\n" + "\n\n".join(paragraphs)
def expand(points):
    blocks = []
    for title, paras in points:
        blocks.append(section(title, *[para(*p) if isinstance(p, tuple) else p for p in paras]))
    return blocks
def make_body(slug, intro, sections, projects, blogs, takeaway, kit_line):
    lines = [intro, f"\n![Cover](/api/blog-covers/{slug})"] + sections
    proj = "\n".join(f"- **[{p['name']}](/projects/{p['slug']})** — {p['desc']}" for p in projects)
    bl = " ".join(f"[{b['name']}](/blog/{b['slug']})" for b in blogs)
    lines += [section("Related reading", para(f"See also {bl}.")), section("Project kits", proj),
              f"\n**Takeaway:** {takeaway} {kit_line}"]
    return "`" + "\n".join(lines) + "`"

