def build_post(m):
    body = make_body(m["slug"], m["intro"], expand(m["points"]), m["projects"], m["blogs"], m["takeaway"], m["kit_line"])
    o = [f'  {{', f'    slug: "{m["slug"]}",', f'    title: "{m["title"]}",']
    if m.get("seoTitle"): o.append(f'    seoTitle: "{m["seoTitle"]}",')
    o += [f'    excerpt: "{m["excerpt"]}",', f'    category: "{m["category"]}",', f'    readTime: "{m["readTime"]}",', f'    date: "{m["date"]}",', f'    body: {body},', '  },']
    return "\n".join(o)

def main():
    c = BLOG_TS.read_text()
    if 'slug: "hybrid-search-rag-explained"' in c:
        print("Posts 10-24 already present")
        return
    ins = "\n".join(build_post(p) for p in POSTS)
    c = c.replace("\n];", f"\n{ins}\n];")
    BLOG_TS.write_text(c)
    n = len(re.findall(r'^\s+slug: "', c, re.M))
    print(f"Added {len(POSTS)} posts. Total: {n}")

if __name__ == "__main__":
    main()
